// SF-112. Projections and structure prices use the same ordinary-tax-only calculation.
let allianceIncomeSnapshot=null,allianceIncomeLoading=false;
function allianceIncomeEmpty(){return {metal:0,crystal:0,eonium:0};}
function allianceIncomeProjection(tax=Number(state.alliance.tax)||0,bribe=Number(state.alliance.strongEncouragement)||0){
 const ordinary=allianceIncomeEmpty(),encouragement=allianceIncomeEmpty(),snapshot=allianceIncomeSnapshot;
 if(snapshot?.alliance===(state.alliance.registryId||state.alliance.name)&&snapshot.generation===(state.centralResetGeneration||0))for(const s of snapshot.sources)for(const k of Object.keys(RES)){if(s.enabled)ordinary[k]+=Math.floor(s.gross[k]*tax/100);if(s.stronghold)encouragement[k]+=Math.floor(s.gross[k]*bribe/100);}
 return {ordinary,bribe:encouragement,total:Object.fromEntries(Object.keys(RES).map(k=>[k,ordinary[k]+encouragement[k]]))};
}
function allianceOrdinaryProjectedIncome(){return allianceIncomeProjection().ordinary;}
function allianceIncomeAmounts(value){return Object.keys(RES).map(k=>'<span>'+esc(RES[k].label)+' <b>'+nfmt(value?.[k]||0)+'</b></span>').join('');}
function allianceIncomeLedgerHTML(){const projected=allianceIncomeProjection(),ledger=state.alliance.incomeLedger||{},alliance=state.alliance.registryId||state.alliance.name,ready=allianceIncomeSnapshot?.alliance===alliance&&allianceIncomeSnapshot.generation===(state.centralResetGeneration||0);return '<div class="ph"><div class="pt">ALLIANCE INCOME LEDGER</div><span class="meta">'+(ready?allianceIncomeSnapshot.reported+' / '+allianceIncomeSnapshot.planets+' REPORTED':'LOADING REPORTS')+'</span></div><div class="table-wrap"><table class="table alliance-income-ledger"><thead><tr><th>Income</th><th>Projected / tick</th><th>Collected this round</th></tr></thead><tbody>'+[['ordinary','Ordinary tax'],['bribe','Strong Encouragement · bribe'],['total','Total']].map(([key,label])=>{const collected=key==='total'?Object.fromEntries(Object.keys(RES).map(k=>[k,(ledger.ordinary?.[k]||0)+(ledger.bribe?.[k]||0)])):ledger[key];return '<tr><th>'+label+'</th><td><div class="alliance-income-amounts">'+(ready?allianceIncomeAmounts(projected[key]):'Waiting for income reports')+'</div></td><td><div class="alliance-income-amounts">'+allianceIncomeAmounts(collected)+'</div></td></tr>';}).join('')+'</tbody></table></div><p class="fund-copy">Structure prices use ordinary tax only. Bribes are excluded. Projections use the latest reported member income; unreported members are excluded. Collections cover recorded ticks since this feature was enabled.</p>';}
function allianceIncomeControlsHTML(){const a=state.alliance,edit=mayAlliance('tax'),bribeEdit=mayAlliance('strongEncouragement');return '<section class="panel alliance-income-panel"><div class="ph"><div class="pt">MEMBER CONTRIBUTIONS</div><span class="meta">OPTIONAL TAX · MAX 5%</span></div><div class="alliance-tax-controls"><div class="field"><label for="allianceTax">Automatic tax (%)</label><input type="number" id="allianceTax" data-alliance-fund-draft min="0" max="5" step="0.5" value="'+(Number(a.tax)||0)+'" '+(edit?'':'disabled')+'><button class="btn" data-alliance="tax" '+(edit?'':'disabled')+'>SAVE TAX</button></div><div class="alliance-tax-preview" id="allianceTaxPreview" aria-live="polite"></div></div><div class="ph"><div class="pt">STRONG ENCOURAGEMENT</div><span class="meta">STRONGHOLD BRIBE · MAX 7.5%</span></div><div class="alliance-tax-controls"><div class="field"><label for="strongEncouragement">Bribe (%) · steps of 0.5</label><input type="number" id="strongEncouragement" data-alliance-fund-draft min="0" max="7.5" step="0.5" value="'+(Number(a.strongEncouragement)||0)+'" '+(bribeEdit?'':'disabled')+'><button class="btn" data-strong-encouragement '+(bribeEdit?'':'disabled')+'>SAVE BRIBE</button></div><div class="alliance-tax-preview" id="allianceBribePreview" aria-live="polite"></div></div><p class="fund-copy">Own members in the active stronghold galaxy only. Separate from optional ordinary tax, including members with ordinary tax disabled. Configure access in Ranks.</p><div id="allianceIncomeLedger">'+allianceIncomeLedgerHTML()+'</div></section>';}
function updateAllianceIncomePreviews(){const tax=Number(document.getElementById('allianceTax')?.value??state.alliance.tax),bribe=Number(document.getElementById('strongEncouragement')?.value??state.alliance.strongEncouragement)||0,projection=allianceIncomeProjection(tax,bribe),ready=allianceIncomeSnapshot?.alliance===(state.alliance.registryId||state.alliance.name)&&allianceIncomeSnapshot.generation===(state.centralResetGeneration||0);for(const [id,key] of [['allianceTaxPreview','ordinary'],['allianceBribePreview','bribe']]){const el=document.getElementById(id);if(el)el.innerHTML='<small>PROJECTED REVENUE / TICK · '+(key==='ordinary'?'SELECTED TAX':'SELECTED BRIBE')+'</small><div class="alliance-income-amounts">'+(ready?allianceIncomeAmounts(projection[key]):'Waiting for member reports…')+'</div>';}}
async function loadAllianceIncome(){if(allianceIncomeLoading||!state.centralPlayerId||!isAllianceMember('A. Commander'))return;allianceIncomeLoading=true;const context={alliance:state.alliance.registryId||state.alliance.name,generation:state.centralResetGeneration||0};try{const data=await centralDirectoryRequest('/api/alliance-economy');if(context.alliance!==(state.alliance.registryId||state.alliance.name)||context.generation!==(state.centralResetGeneration||0))return;allianceIncomeSnapshot={...data.income,...context};state.alliance.incomeLedger=data.income.ledger;const el=document.getElementById('allianceIncomeLedger');if(el)el.innerHTML=allianceIncomeLedgerHTML();updateAllianceIncomePreviews();if(allianceTab==='structures')renderAlliance();}catch(error){const el=document.getElementById('allianceTaxPreview');if(el)el.textContent=error.message;}finally{allianceIncomeLoading=false;}}
const renderAllianceBeforeIncome=renderAlliance;
renderAlliance=function(...args){const result=renderAllianceBeforeIncome.apply(this,args);updateAllianceIncomePreviews();if(document.getElementById('allianceIncomeLedger')||(allianceTab==='structures'&&!allianceIncomeSnapshot))loadAllianceIncome();return result;};
document.addEventListener('input',e=>{if(['allianceTax','strongEncouragement'].includes(e.target.id))updateAllianceIncomePreviews();});
let encouragementBusy=false,encouragementPending=null;
document.addEventListener('click',async e=>{if(!e.target.closest('[data-strong-encouragement]')||encouragementBusy)return;const tax=Number(document.getElementById('strongEncouragement')?.value);if(!Number.isFinite(tax)||tax<0||tax>7.5||!Number.isInteger(tax*2))return notify('Choose 0–7.5% in steps of 0.5%.',true);if(!mayAlliance('strongEncouragement'))return notify('Your rank cannot set Strong Encouragement.',true);encouragementBusy=true;const context=allianceEventContext();try{if(!encouragementPending||!sameAllianceEventContext(encouragementPending.context)||encouragementPending.payload.tax!==tax)encouragementPending={context,payload:{action:'strongEncouragement',tax,generation:context.generation,revision:planetDirectoryRevision,operationId:crypto.randomUUID()}};const result=await centralDirectoryRequest('/api/alliance-policy',encouragementPending.payload);encouragementPending=null;if(!sameAllianceEventContext(context))return;state.alliance.strongEncouragement=result.tax;planetDirectoryRevision=result.revision;await refreshAfterCentralWrite();notify('Strong Encouragement saved.');}catch(error){if([400,403,409].includes(error.status))encouragementPending=null;if(error.status===409)await refreshAfterCentralWrite();notify(error.message,true);}finally{encouragementBusy=false;}});
function recordAllianceIncomeTick(gross){state.allianceIncomeTicks=state.allianceIncomeTicks||[];if(state.allianceIncomeTicks.some(r=>r.tick===state.tick))return;state.allianceIncomeTicks.push({tick:state.tick,gross:copy(gross),enabled:!!state.userSettings.allianceTaxEnabled,alliance:state.alliance.registryId||state.alliance.name});}
function applyAllianceIncomeTax(planet){state.appliedAllianceIncomeTax=state.appliedAllianceIncomeTax||{};for(const k of Object.keys(RES)){const total=planet.allianceIncomeTaxTotal?.[k]||0,previous=state.appliedAllianceIncomeTax[k]||0;if(total>previous){state.resources[k]=Math.max(0,state.resources[k]-(total-previous));state.appliedAllianceIncomeTax[k]=total;}}}

